1	package server
2	
3	import (
4		"net/http"
5		"net/url"
6		"strconv"
7		"sync"
8		"time"
9	)
10	
11	// auditCapacity bounds the retained event history. Once the log is full the
12	// oldest events are evicted while sequence numbers keep increasing and are
13	// never reused.
14	const auditCapacity = 10000
15	
16	// Audit actions, one per recorded entry point.
17	const (
18		auditObjectUpload      = "object.upload"
19		auditBundleImport      = "bundle.import"
20		auditDeltaBundleImport = "delta_bundle.import"
21		auditPinPut            = "pin.put"
22		auditPinDelete         = "pin.delete"
23		auditGCPreview         = "gc.preview"
24		auditGCCollect         = "gc.collect"
25		auditProviderPut       = "provider.put"
26		auditProviderDelete    = "provider.delete"
27		auditRetrievalLocal    = "retrieval.local"
28		auditRetrievalFetch    = "retrieval.fetch"
29	)
30	
31	// auditEvent is one recorded outcome of a successful request. Fields that
32	// do not apply to an action are nil and serialize as null.
33	type auditEvent struct {
34		Seq        int64     `json:"seq"`
35		At         time.Time `json:"at"`
36		Action     string    `json:"action"`
37		CID        *string   `json:"cid"`
38		Result     string    `json:"result"`
39		Objects    *int      `json:"objects"`
40		Bytes      *int      `json:"bytes"`
41		ProviderID *string   `json:"providerId"`
42	}
43	
44	// auditRecord carries the commit-time facts of one event; the log assigns
45	// the sequence number and timestamp when the event is appended.
46	type auditRecord struct {
47		action     string
48		result     string
49		cid        *string
50		objects    *int
51		bytes      *int
52		providerID *string
53	}
54	
55	// objectAuditRecord builds the record for an action that stores an object:
56	// bytes is the object body length and the result names whether this request
57	// created the object. Remote fetches use the retrieved_* result names.
58	func objectAuditRecord(action string, obj *object, created bool, providerID *string) auditRecord {
59		result := "existing"
60		if created {
61			result = "created"
62		}
63		if action == auditRetrievalFetch {
64			result = "retrieved_existing"
65			if created {
66				result = "retrieved_created"
67			}
68		}
69		return auditRecord{
70			action:     action,
71			result:     result,
72			cid:        strPtr(obj.cid),
73			bytes:      intPtr(obj.size),
74			providerID: providerID,
75		}
76	}
77	
78	func strPtr(s string) *string { return &s }
79	func intPtr(v int) *int       { return &v }
80	
81	// auditLog is a process-local ring of recent audit events. Appends happen
82	// under the caller's business lock so the event order matches the commit
83	// order of the recorded operations. The log takes no part in pinning,
84	// garbage collection, storage statistics or content addressing, and is not
85	// retained across restarts.
86	type auditLog struct {
87		mu     sync.Mutex
88		ring   []auditEvent
89		start  int // ring index of the oldest retained event
90		length int
91		next   int64 // next sequence number to assign
92	}
93	
94	func newAuditLog() *auditLog {
95		return &auditLog{ring: make([]auditEvent, auditCapacity), next: 1}
96	}
97	
98	// append records one event with the next sequence number, evicting the
99	// oldest event once the log is full. A nil log discards the record, so
100	// business code needs no nil checks of its own.
