89	// bundleRootJSON is the strictly decoded root section of an import body.
90	// Pointer fields distinguish a missing key from a zero value; numbers stay
91	// raw so quoted strings are rejected as type errors.
92	type bundleRootJSON struct {
93		CID       *string          `json:"cid"`
94		Size      *json.RawMessage `json:"size"`
95		ChunkSize *json.RawMessage `json:"chunkSize"`
96		Chunks    *[]string        `json:"chunks"`
97	}
98	
