69	func TestPinCreateUpdateListDelete(t *testing.T) {
70		h := Handler()
71		a := upload(t, h, []byte("alpha"))
72		b := upload(t, h, []byte("beta"))
73	
74		// Create a permanent pin.
75		rec := putPin(t, h, a.CID, `{}`, "application/json")
76		if rec.Code != http.StatusCreated {
77			t.Fatalf("create status = %d, want %d", rec.Code, http.StatusCreated)
78		}
79		resp := decodePinResponse(t, rec)
80		if resp.CID != a.CID || resp.ExpiresAt != nil {
81			t.Fatalf("unexpected pin response: %+v", resp)
82		}
83	
84		// Null expiresAt is also permanent.
85		rec = putPin(t, h, b.CID, `{"expiresAt":null}`, "application/json")
86		if rec.Code != http.StatusCreated {
87			t.Fatalf("null-expiry create status = %d, want %d", rec.Code, http.StatusCreated)
88		}
89	
90		// Updating an in-force pin returns 200.
91		expiry := time.Now().Add(time.Hour).UTC().Format(time.RFC3339)
92		rec = putPin(t, h, a.CID, `{"expiresAt":"`+expiry+`"}`, "application/json")
93		if rec.Code != http.StatusOK {
94			t.Fatalf("update status = %d, want %d", rec.Code, http.StatusOK)
95		}
96		resp = decodePinResponse(t, rec)
97		if resp.ExpiresAt == nil || !resp.ExpiresAt.Equal(time.Now().Add(time.Hour).UTC().Truncate(time.Second)) {
98			t.Fatalf("unexpected updated expiry: %+v", resp.ExpiresAt)
99		}
100	
101		// Listing returns both pins, sorted by cid, permanent ones null.
102		list := listPins(t, h)
103		if len(list.Pins) != 2 {
104			t.Fatalf("listed %d pins, want 2", len(list.Pins))
105		}
106		if list.Pins[0].CID >= list.Pins[1].CID {
107			t.Fatalf("pins not sorted by cid: %+v", list.Pins)
108		}
109		byCID := map[string]pinResponse{}
110		for _, p := range list.Pins {
111			byCID[p.CID] = p
112		}
113		if byCID[a.CID].ExpiresAt == nil {
114			t.Fatal("updated pin should carry an expiration")
115		}
116		if byCID[b.CID].ExpiresAt != nil {
117			t.Fatal("permanent pin should list expiresAt as null")
118		}
119	
120		// Delete, then delete again.
121		req := httptest.NewRequest(http.MethodDelete, "/v1/pins/"+a.CID, nil)
122		rec = httptest.NewRecorder()
123		h.ServeHTTP(rec, req)
124		if rec.Code != http.StatusNoContent {
125			t.Fatalf("delete status = %d, want %d", rec.Code, http.StatusNoContent)
126		}
127		rec = httptest.NewRecorder()
128		h.ServeHTTP(rec, httptest.NewRequest(http.MethodDelete, "/v1/pins/"+a.CID, nil))
129		if rec.Code != http.StatusNotFound {
130			t.Fatalf("second delete status = %d, want %d", rec.Code, http.StatusNotFound)
131		}
132		assertErrorCode(t, rec, "pin_not_found")
133	
134		if list := listPins(t, h); len(list.Pins) != 1 || list.Pins[0].CID != b.CID {
135			t.Fatalf("unexpected pins after delete: %+v", list.Pins)
136		}
137	}
