250	func TestGarbageCollection(t *testing.T) {
251		h := Handler()
252		pinned := upload(t, h, []byte("pinned"))
253		unpinned := upload(t, h, []byte("unpinned"))
254		expiring := upload(t, h, []byte("expiring pin"))
255	
256		if rec := putPin(t, h, pinned.CID, `{}`, "application/json"); rec.Code != http.StatusCreated {
257			t.Fatalf("pin status = %d", rec.Code)
258		}
259		short := time.Now().Add(150 * time.Millisecond).UTC().Format(time.RFC3339Nano)
260		if rec := putPin(t, h, expiring.CID, `{"expiresAt":"`+short+`"}`, "application/json"); rec.Code != http.StatusCreated {
261			t.Fatalf("pin status = %d", rec.Code)
262		}
263		time.Sleep(300 * time.Millisecond)
264	
265		// Dry run previews without deleting.
266		code, preview := runGC(t, h, "?dryRun=true")
267		if code != http.StatusOK {
268			t.Fatalf("dry run status = %d, want %d", code, http.StatusOK)
269		}
270		if !preview.DryRun || preview.Objects != 2 || preview.Bytes != len("unpinned")+len("expiring pin") {
271			t.Fatalf("unexpected dry run response: %+v", preview)
272		}
273		if len(preview.CIDs) != 2 || preview.CIDs[0] >= preview.CIDs[1] {
274			t.Fatalf("dry run cids not sorted: %+v", preview.CIDs)
275		}
276		getRec := httptest.NewRecorder()
277		h.ServeHTTP(getRec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+unpinned.CID, nil))
278		if getRec.Code != http.StatusOK {
279			t.Fatalf("dry run must not delete, GET status = %d", getRec.Code)
280		}
281	
282		// Real run deletes only the unpinned and the expired-pin objects.
283		code, result := runGC(t, h, "")
284		if code != http.StatusOK {
285			t.Fatalf("gc status = %d, want %d", code, http.StatusOK)
286		}
287		if result.DryRun || result.Objects != 2 || result.Bytes != preview.Bytes {
288			t.Fatalf("unexpected gc response: %+v", result)
289		}
290		for _, cid := range []string{unpinned.CID, expiring.CID} {
291			for _, suffix := range []string{"", "/manifest"} {
292				rec := httptest.NewRecorder()
293				h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+cid+suffix, nil))
294				if rec.Code != http.StatusNotFound {
295					t.Fatalf("GET collected object%s: status = %d, want %d", suffix, rec.Code, http.StatusNotFound)
296				}
297				assertErrorCode(t, rec, "object_not_found")
298			}
299		}
300		// The pinned object survives.
301		rec := httptest.NewRecorder()
302		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/v1/objects/"+pinned.CID, nil))
303		if rec.Code != http.StatusOK {
304			t.Fatalf("pinned object collected, GET status = %d", rec.Code)
305		}
306	
307		// Re-uploading collected content yields the original cid as a new object.
308		again := upload(t, h, []byte("unpinned"))
309		if !again.Created || again.CID != unpinned.CID {
310			t.Fatalf("re-upload = %+v, want created=true cid=%q", again, unpinned.CID)
311		}
312	
313		// The re-uploaded object is itself unpinned, so the next sweep collects
314		// exactly it; after that nothing is left.
315		_, result = runGC(t, h, "")
316		if result.Objects != 1 || result.Bytes != len("unpinned") || len(result.CIDs) != 1 || result.CIDs[0] != unpinned.CID {
317			t.Fatalf("second gc should collect only the re-upload: %+v", result)
318		}
319		_, result = runGC(t, h, "")
320		if result.Objects != 0 || result.Bytes != 0 || len(result.CIDs) != 0 {
321			t.Fatalf("third gc should be empty: %+v", result)
322		}
323	}
