364	func TestGCPinOrderingGuarantee(t *testing.T) {
365		h := Handler()
366		obj := upload(t, h, []byte("race me"))
367	
368		// Pin first: a subsequent gc must keep the object.
369		if rec := putPin(t, h, obj.CID, `{}`, "application/json"); rec.Code != http.StatusCreated {
