// commitMetadata appends one metadata revision for cid when expected matches
// the current revision number (0 before the first write). The check and the
// append are atomic, so exactly one of several concurrent writers with the
// same expected revision succeeds. Metadata creates no pin, no audit event
// and no statistics change.
func (s *store) commitMetadata(cid string, expected int64, contentType *string, labels map[string]string, now time.Time) (metadataRevision, bool, string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.objects[cid]; !ok {
		return metadataRevision{}, false, "object_not_found"
	}
	history := s.metadata[cid]
	if int64(len(history)) != expected {
		return metadataRevision{}, false, "revision_conflict"
	}
	rev := metadataRevision{
		revision:    expected + 1,
		contentType: contentType,
		labels:      labels,
		updatedAt:   now.UTC(),
	}
	s.metadata[cid] = append(history, rev)
	return rev, expected == 0, ""
}

// metadataAt returns the current metadata revision for cid, or the requested
// historical revision when revision > 0. The string result names the error
// code when no revision is returned: object_not_found, metadata_not_found or
// metadata_revision_not_found.
func (s *store) metadataAt(cid string, revision int64) (metadataRevision, string) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if _, ok := s.objects[cid]; !ok {
		return metadataRevision{}, "object_not_found"
	}
	history := s.metadata[cid]
	if len(history) == 0 {
		return metadataRevision{}, "metadata_not_found"
	}
	if revision == 0 {
		return history[len(history)-1], ""
	}
	if revision > int64(len(history)) {
		return metadataRevision{}, "metadata_revision_not_found"
	}
	return history[revision-1], ""
}
