	n := utf8.RuneCountInString(s)
	return n >= 1 && n <= maxMetadataContentTypeLen && !hasControl(s)
}

// validMetadataLabels reports whether the label set obeys the count, key and
// value bounds.
func validMetadataLabels(labels map[string]string) bool {
	if len(labels) > maxMetadataLabels {
		return false
	}
	for k, v := range labels {
		if !metadataLabelKey.MatchString(k) {
			return false
		}
		if utf8.RuneCountInString(v) > maxMetadataLabelValueLen || hasControl(v) {
			return false
		}
	}
	return true
}

// hasControl reports whether s contains a Unicode control character.
func hasControl(s string) bool {
	for _, r := range s {
		if unicode.IsControl(r) {
			return true
		}
	}
	return false
}
